# Exact DP over leak choices on days 1..8 given surfaced: {5:"d3-2", 6:"d3-3", 8:"d4-2", 9:"d6-1", 10:"d6-2"}
surfaced_by_day = {5: "d3-2", 6: "d3-3", 8: "d4-2", 9: "d6-1", 10: "d6-2"}
# State: (leaked_frozenset, pending_for_next_day_doc_or_None) -> prob
# Actually delay is 2 or 3: leak on day d surfaces on d+2 (0.5) or d+3 (0.5).
# Track scheduled surfaces on days 1..10 as a dict {surface_day: count_or_docs}
states = {(frozenset(), ()): 1.0}  # (leaked_set, tuple of (surf_day, doc_id))
for d in range(1, 9):
    new_states = {}
    for (leaked, sched), prob in states.items():
        el = elig_w(d, leaked)
        if not el:
            # 0 leaks
            ns = (leaked, sched)
            new_states[ns] = new_states.get(ns, 0.0) + prob
        else:
            # no leak (0.35)
            ns = (leaked, sched)
            new_states[ns] = new_states.get(ns, 0.0) + prob * 0.35
            tot = sum(el.values())
            for doc_id, w in el.items():
                for delay in (2, 3):
                    sd = d + delay
                    # Quick prune: if sd <= 10, must match surfaced_by_day
                    if sd <= 10 and surfaced_by_day.get(sd) != doc_id:
                        continue
                    # Also cannot schedule two leaks on same sd <= 10
                    if sd <= 10 and any(sdd == sd for sdd, _ in sched):
                        continue
                    nsched = tuple(sorted(sched + ((sd, doc_id),)))
                    nleaked = leaked | {doc_id}
                    p_step = prob * 0.65 * (w / tot) * 0.5
                    new_states[(nleaked, nsched)] = new_states.get((nleaked, nsched), 0.0) + p_step
    states = new_states
total_leak_prob = 0.0
for (leaked, sched), prob in states.items():
    # Check all surfaced_by_day in 1..10 are present in sched
    got = {sd: doc_id for sd, doc_id in sched if sd <= 10}
    if got == surfaced_by_day:
        total_leak_prob += prob
ll = math.log(total_leak_prob)

